<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{player,players,savePlayer,selectPlayer}from'../stores';const name=ref(''),error=ref(''),router=useRouter();function choose(id:string){selectPlayer(id);router.push('/home')}function add(){error.value='';if(!savePlayer(name.value)){error.value='Inserisci un nome nuovo e valido.';return}router.push('/home')}</script>
<template><section class="screen sub players-screen"><RouterLink to="/home" class="back">⌂ HOME</RouterLink><h1>👥 Giocatori</h1><p class="section-help">Chi sta giocando?</p><div class="player-list"><button v-for="p in players" :key="p.id" :class="{active:p.id===player.id}" @click="choose(p.id)"><span><b>{{p.nickname}}</b><small>Record: {{p.best}} · Time Attack: {{p.timeAttackBest}}</small></span><strong>{{p.id===player.id?'✓':'›'}}</strong></button></div><h2>Aggiungi giocatore</h2><form class="add-player" @submit.prevent="add"><input v-model="name" maxlength="18" autocomplete="nickname" placeholder="Nome" aria-label="Nuovo alias"><small v-if="error" class="form-error">{{error}}</small><button class="primary">AGGIUNGI <span>＋</span></button></form></section></template>
